import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score

MAX_DRIVERS = 3

def design(feats):
    # Find highly correlated pairs (|r| >= 0.6)
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                correlated_pairs.add((min(fid1,fid2), max(fid1,fid2)))

    # Remove near-duplicates (keep one from each pair)
    keep_ids = set(feats.ids)
    for fid1, fid2 in correlated_pairs:
        if fid1 in keep_ids and fid2 in keep_ids:
            # Prefer the one with higher absolute mean_y1-mean_y0
            idx1 = feats.column(fid1)
            idx2 = feats.column(fid2)
            mean_diff1 = np.mean(feats.x[feats.y==1,idx1]) - np.mean(feats.x[feats.y==0,idx1])
            mean_diff2 = np.mean(feats.x[feats.y==1,idx2]) - np.mean(feats.x[feats.y==0,idx2])
            if abs(mean_diff1) >= abs(mean_diff2):
                keep_ids.remove(fid2)
            else:
                keep_ids.remove(fid1)

    # Compute effect sizes for remaining features
    effects = []
    for fid in keep_ids:
        idx = feats.column(fid)
        mean_diff = np.mean(feats.x[feats.y==1,idx]) - np.mean(feats.x[feats.y==0,idx])
        t_stat, _ = stats.ttest_ind(feats.x[feats.y==1,idx], feats.x[feats.y==0,idx])
        auc = roc_auc_score(feats.y, feats.x[:,idx])
        effects.append((fid, abs(mean_diff), abs(t_stat), auc))

    # Sort by effect size (mean difference, then t-stat, then AUC)
    effects.sort(key=lambda x: (-x[1], -x[2], -x[3]))

    # Try to find a product term
    drivers = []
    columns = []
    products = []
    loadings = {}

    # Check top features for interaction
    top_features = [f for f, _, _, _ in effects[:5]]

    # Look for product terms among correlated pairs
    for fid1, fid2 in correlated_pairs:
        if fid1 in top_features and fid2 in top_features:
            # Add both features to columns
            if fid1 not in columns:
                columns.append(fid1)
            if fid2 not in columns:
                columns.append(fid2)
            # Add product term
            products.append((fid1, fid2))

    # If we have product terms, add the features involved
    if products:
        for fid1, fid2 in products:
            if fid1 not in columns:
                columns.append(fid1)
            if fid2 not in columns:
                columns.append(fid2)
        # Use strongest feature as driver
        if effects:
            drivers = [effects[0][0]]
    else:
        # No interaction found, just use top features
        for i, (fid, _, _, _) in enumerate(effects):
            if i < MAX_DRIVERS:
                drivers.append(fid)
            columns.append(fid)

    # Keep it small - limit total terms
    total_terms = len(columns) + len(products)
    if total_terms > 12:
        # Reduce to minimal necessary terms
        columns = columns[:3]
        products = products[:1]
        drivers = drivers[:1] if drivers else []

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

